     1	/* The portal's loading state.
     2	 *
     3	 * Mounted through Next's route-segment `loading.tsx`, so it replaces the WHOLE
     4	 * page body until that route's server component has finished — which is the
     5	 * point: these pages are `force-dynamic` and several of them wait on real work
     6	 * (IMAP round trips on Mail, Mailcow discovery on Mailboxes, Stripe on
     7	 * Billing). Without it a route paints its cheap markup first and drops the rest
     8	 * in a beat later, so every navigation looked half-built for a moment.
     9	 *
    10	 * Deliberately server-rendered and CSS-only — no client component, no
    11	 * JavaScript, no hydration — because it has to be on screen during exactly the
    12	 * window where the page's own JavaScript is not ready yet.
    13	 *
    14	 * The mark is the real Logo's geometry rather than a spinner: its three slabs
    15	 * light in sequence, a gradient arc sweeps the ring, and the whole cycle is
    16	 * built to loop seamlessly (every animated property returns to its start value).
    17	 */
    18	export function Preloader({ label = "Loading" }: { label?: string }) {
    19	  return (
    20	    <div className="nx-pre grid h-full w-full place-items-center" role="status" aria-live="polite">
    21	      <div className="flex flex-col items-center gap-7">
    22	        <div className="relative grid h-[104px] w-[104px] place-items-center">
    23	          {/* Soft bloom behind the mark, breathing in time with the sweep. */}
    24	          <span aria-hidden className="nx-pre-halo" />
    25	          {/* The sweeping arc. */}
    26	          <span aria-hidden className="nx-pre-ring" />
    27	          {/* The mark itself: outer plate from the real Logo, slabs re-drawn as
    28	              three separate paths so they can light one after another. A single
    29	              path (as Logo ships it) can only fade as one lump. */}
    30	          <svg width="60" height="60" viewBox="-56 -56 112 112" fill="none" aria-hidden className="relative">
    31	            <defs>
    32	              <linearGradient id="nxpre" x1="0" y1="0" x2="1" y2="1">
    33	                <stop offset="0" stopColor="#3fbcd8" />
    34	                <stop offset="0.5" stopColor="#4f7cff" />
    35	                <stop offset="1" stopColor="#d623e1" />
    36	              </linearGradient>
    37	            </defs>
    38	            <path className="nx-pre-slab" style={{ animationDelay: "0ms" }}
    39	                  d="M-30 -30 L-16 -30 L30 28 L16 28 Z" fill="url(#nxpre)" />
    40	            <path className="nx-pre-slab" style={{ animationDelay: "150ms" }}
    41	                  d="M12 -30 L30 -30 L30 12 L12 12 Z" fill="url(#nxpre)" />
    42	            <path className="nx-pre-slab" style={{ animationDelay: "300ms" }}
    43	                  d="M-30 -8 L-13 -8 L-13 30 L-30 30 Z" fill="url(#nxpre)" />
    44	          </svg>
    45	        </div>
    46	
    47	        <div className="flex flex-col items-center gap-3">
    48	          <span className="text-[11px] font-bold uppercase tracking-[0.34em] text-tx-faint">Nxeon</span>
    49	          {/* Indeterminate rail — a real progress bar would be a lie, we have no
    50	              percentage to report. */}
    51	          <span aria-hidden className="nx-pre-rail">
    52	            <span className="nx-pre-bar" />
    53	          </span>
    54	        </div>
    55	        <span className="sr-only">{label}</span>
    56	      </div>
    57	    </div>
    58	  );
    59	}
