      if (document.hidden) return;
      if (now - last < 1000 / 30) return;
      last = now;
      const t = still ? 0 : (now - t0) / 1000;
      /* one clock for both layers, so a bundle that dives behind the rack and
         reappears in front stays in step */
      paint(gb!, W, H, BACK, t);
      paint(gf!, W, H, FRONT, t);
    }

    size();
    const ro = new ResizeObserver(size);
    ro.observe(b);
    raf = requestAnimationFrame(frame);
    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
  }, []);

  return (
    <div className={"relative isolate " + (className.includes("h-[") ? "" : "aspect-[5/4] w-full ") + className}>
      {/* faded on every side, so the streams end in air rather than at a box
          edge — and so they cannot bleed under whatever sits next to them */}
      <canvas ref={back} aria-hidden className="z-0" style={FADE} />
      {/* the shadow it casts on nothing in particular, breathing with the rise */}
      <span aria-hidden
            className="nx-levitate-shadow absolute left-1/2 top-[80%] z-[5] h-[9%] w-[38%] -translate-x-1/2 rounded-[50%]"
            style={{ background: "radial-gradient(circle, rgba(2,6,20,0.9), rgba(2,6,20,0) 70%)" }} />
      <span className="pointer-events-none absolute left-1/2 top-1/2 z-10 h-[76%]
                       -translate-x-1/2 -translate-y-1/2">
        <img src="/nx/rack.webp" alt="" aria-hidden draggable={false}
             className="nx-levitate block h-full w-auto max-w-none select-none object-contain
                        drop-shadow-[0_26px_54px_rgba(0,4,20,0.8)]" />
      </span>
      <canvas ref={front} aria-hidden className="pointer-events-none z-20" style={FADE} />
    </div>
  );
}

