const { chromium } = require("playwright");
(async () => {
  const browser = await chromium.launch();
  const version = browser.version();
  console.log("chromium version:", version);
  const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
  await page.goto("http://127.0.0.1:3021/login", { waitUntil: "domcontentloaded" });
  await page.fill("input[type=email], input[name=email]", "admin@nxeon.local");
  await page.fill("input[type=password], input[name=password]", "iCwEt7PDdo0ne3YM");
  await Promise.all([
    page.waitForURL(u => !u.pathname.includes("/login"), { timeout: 45000 }).catch(()=>{}),
    page.click("button.btn-primary"),
  ]);
  await page.waitForTimeout(1000);
  await page.goto("http://127.0.0.1:3021/dashboard", { waitUntil: "domcontentloaded" });
  await page.waitForTimeout(1000);

  const result = await page.evaluate(() => {
    let found = [];
    for (const sheet of document.styleSheets) {
      let rules;
      try { rules = sheet.cssRules; } catch(e) { continue; }
      function scan(rules, path) {
        for (const r of rules) {
          if (r instanceof CSSKeyframesRule && (r.name === "nx-levitate" || r.name === "nx-float" || r.name==="nx-pre-slab")) {
            found.push({ name: r.name, path, cssText: r.cssText.slice(0,120) });
          } else if (r.cssRules) {
            scan(r.cssRules, path + " > " + (r.selectorText||r.conditionText||r.cssText.slice(0,40)));
          }
        }
      }
      scan(rules, sheet.href||"inline");
    }
    const el = document.querySelector(".nx-levitate");
    return {
      found,
      elExists: !!el,
      elAnims: el ? el.getAnimations().length : null,
      elComputedAnimName: el ? getComputedStyle(el).animationName : null,
    };
  });
